documents.splice(7, 0, {slug:"mcp",title:"MCP tool reference",group:"Integrate",description:"The typed interface your agent uses to fork infrastructure, explore changes, and inspect their consequences across the documented lenses.",sections:[
  section("using-tools", "Using the tools", ["Emfirge runs as an MCP server that your agent invokes over the local stdio connection. Each tool below is a registered operation; select its linked page for the full parameter and response details.", "Persist the analysis_id and branch_id returned by your own calls. Do not substitute IDs from screenshots or examples. A compatible engine is required for branch operations."]),
  ...mcpIndexGroups.map(([id, names]) => section(id, id, [], {table: {headers: ["Tool", "What it does"], rows: names.map(name => { const tool = mcpTools.find(candidate => candidate.name === name)!; return [`[${tool.name}](${mcpIndexRoutes[name]})`, tool.description]; })}})),
]});
const extra = (slug: string, title: string, group: string, description: string, sections: DocSection[]): Doc => ({slug,title,group,description,sections});
const legacyDocs: Doc[] = [
  extra("how-it-works","How the fork works","Get started","Build a read-only graph, fork it, model a change, and inspect consequences before deployment.",[section("harness","The harness between AI and cloud", ["An agent should not need direct access to a live account. Emfirge sits between the agent and cloud as a safe workspace: the agent proposes, Emfirge branches and measures the change, and your own pipeline decides what to apply." ]),section("workflow","The workflow", ["A scan builds a connected graph from a read-only role. Fork a completed analysis with `emfirge_create_branch`, add an operation with `emfirge_apply_change`, then inspect `emfirge_branch_diff` and `emfirge_branch_verdict`."],{code:'emfirge_create_branch({ base_analysis_id: "<analysis_id>", name: "restrict-public-access" })\nemfirge_apply_change({ branch_id: "<branch_id>", op: "modify", resource_type: "rds_instance", resource_id: "<database_id>", fields: { publicly_accessible: false } })\nemfirge_branch_verdict({ branch_id: "<branch_id>" })',language:"MCP tool calls"}),section("limits","Honest limits",["Branches are models, not deployments. Emfirge does not apply branch changes to AWS, and a result from any one lens does not prove application connectivity or every operational consequence. Re-scan when the live environment changes."])]),
  extra("graph","The infrastructure graph","Understand consequences","Explore attack paths, blast radius, chokepoints, and toxic combinations as queries over one graph.",[section("map","What the graph is",["Every scanned resource becomes a node and every relationship a directed edge. The public internet is a first-class node, so reachability is a literal path. The engine models roughly 20 service types and relationships such as `REACHES`, `uses_iam_role`, `can_access`, `REFERENCES_SECRET`, and subnet/VPC containment." ]),section("weights","Rank routes by effort",["Edges carry exploit-difficulty weights from 0 to 3. Path ranking uses effort, not simply hop count: a five-hop route of trivial steps can outrank a two-hop route needing a shell and stolen credentials."],{table:{headers:["Weight","Meaning"],rows:[["0","No additional modeled difficulty"],["1","Low modeled effort"],["2","Moderate modeled effort"],["3","High modeled effort"]]}}),section("queries","One graph, many queries",["Attack paths are ranked by effort. Blast radius is an outbound-only search from a node. Chokepoints use betweenness centrality. Toxic combinations are nine curated multi-signal patterns, and orphaned resources are disconnected nodes often indicating cleanup or cost work."]),section("limits","Rules and limits",["The engine runs 58 deterministic rules across 17 service families and produces a 0–100 posture score, higher is safer, across security, availability, cost, and disaster recovery. Path-finding and blast radius are capped at 5 hops. The graph is a scan snapshot, not live AWS; coverage and exploit weights are bounded heuristics."])]),
  extra("security","Security as one lens","Safety & privacy","Emfirge is the harness between your AI agent and cloud: fork the infrastructure graph, model a proposed change, and inspect its consequences across the documented lenses before production. Security and reachability are one lens; read-only IAM access, scoped trust, temporary credentials, deterministic analysis, and revocation keep that lens bounded.",[section("role","The role",["Emfirge reads through a read-only IAM role you own and control, with no write permissions. The role trusts the configured account with ExternalId `aws-risk-agent` and uses one-hour temporary STS credentials that are never stored. Delete the CloudFormation stack to revoke access."]),section("setup","Set it up",["Ask your assistant for setup help, open the pre-filled CloudFormation URL, acknowledge the IAM-resources checkbox, create the stack (about 30 seconds), and copy `RoleArn` from Outputs before scanning."]),section("deterministic","Deterministic backend",["Scanning, rules, graph analysis, and verify-fix are pure computation: the same input produces the same output. Prose summaries are the only place a model is used, never inside the MCP path."]),section("errors","Retention and errors",["Scan data is retained for 90 days and then auto-deleted; the CLI can wipe it immediately. A 403 usually means trust or ExternalId, a 404 means the analysis was not found, and a 429 means the five-scans-per-account-per-day limit."])]),
  extra("privacy","Privacy modes","Safety & privacy","Control which recognized AWS identifiers are tokenized before results reach your model.",[section("tokenization","How tokenization works",["The local MCP replaces recognized AWS identifiers with stable local tokens such as `SG_001` and `S3_001`. Later calls expand tokens locally, call the backend, and tokenize again. The mapping stays on your machine and is not sent to Emfirge or the model."],{code:'LLM sees:       "SG_001 reaches S3_001"\nlocal mapping:  SG_001 = <local security-group ID>\n                S3_001 = <local bucket ID>',language:"Example"}),section("modes","The three modes",["`strict` (default) tokenizes recognized AWS IDs, ARNs, account IDs, names, and IPs. `balanced` tokenizes common identifiers while retaining selected context. `off` leaves identifiers raw."]),section("change","Change the mode",["Use the CLI or set `EMFIRGE_PRIVACY` in client configuration."],{code:"npx @emfirge/mcp privacy\nnpx @emfirge/mcp privacy strict",language:"Terminal"}),section("boundary","Backend and report URLs",["The backend receives data required for analysis. Credentials in presigned report URLs are scrubbed. Derived graph labels may not be recognized identifiers, so tokenization is not a completeness guarantee."])]),
  extra("cli","CLI reference","CLI","Install, inspect, configure, and remove the Emfirge MCP client from the terminal.",[section("overview","The package and server",["With no subcommand the package runs as an MCP stdio server; with a subcommand it manages your install."]),section("commands","Commands",["`install` wires the server into detected client configs; `--privacy` avoids the prompt and defaults to strict. `status` prints wired clients, backend URL, and privacy mode. `privacy` shows or sets strict, balanced, or off. `tokens` lists local mappings at `~/.emfirge/tokens.json`, which never leaves your machine."],{code:"npx @emfirge/mcp --help\nnpx @emfirge/mcp install --privacy=strict\nnpx @emfirge/mcp status\nnpx @emfirge/mcp privacy strict\nnpx @emfirge/mcp tokens",language:"Terminal"}),section("purge","Purge scan data",["`purge --role-arn <role-arn>` deletes local token mappings and server-side scan data for that role. This permanently deletes records and has no undo."],{code:"npx @emfirge/mcp purge --role-arn arn:aws:iam::<account>:role/<name>",language:"Terminal",note:"Irreversible"})]),
  extra("self-host","Self-hosting","Self-hosting","Point the thin MCP client at your own backend with environment variables.",[section("backend","Point at your own backend",["The default backend is `https://emfirge.cloud/api`. Set `EMFIRGE_BASE_URL` in each client config. The thin MCP calls backend endpoints and tokenizes responses locally; dashboard URLs derive from the API base by stripping `/api`." ]),section("environment","Environment variables",[],{table:{headers:["Variable","Purpose and default"],rows:[["EMFIRGE_BASE_URL","Backend URL; default https://emfirge.cloud/api"],["EMFIRGE_PRIVACY","strict, balanced, or off"],["EMFIRGE_TRUSTED_ACCOUNT_ID","Trusted AWS account; default 000000000000"],["EMFIRGE_EXTERNAL_ID","Trust ExternalId; default aws-risk-agent"],["EMFIRGE_TEMPLATE_URL","Template URL used by setup help"]]}}),section("license","Open source",["The MCP and a public backend mirror are open source under BUSL 1.1 (free for non-production and small production use; converts to Apache 2.0 in 2030)."])]),
  extra("faq","FAQ","Reference","Plain-language answers about Emfirge, AWS access, privacy, limits, and self-hosting.",[section("basics","What does Emfirge do?",["Emfirge is the harness between your AI agent and cloud: it forks the infrastructure graph so you can model a proposed change and inspect its consequences before applying anything. Security and reachability are one lens; ask what to fix first, how someone could reach a database, or whether a change helps."]),section("start","What do I need?",["An AWS account, a region, and a read-only connection. Start with the [quickstart](/docs/quickstart). MCP is simply the connection that lets an AI assistant use tools. A demo uses made-up infrastructure with the real analysis engine."]),section("safety","Will it change anything?",["No. Possible fixes run on a temporary copy of the cloud map. Revoke access by deleting the setup stack. See [Security model](/docs/security) and [Privacy modes](/docs/privacy)."]),section("limits","How long and how often?",["Scans usually take 30–60 seconds and are limited to five per AWS account per day. Findings, attack paths, possible fixes, and compliance checks do not consume another scan. Coverage is not every AWS issue."]),section("next","What after a finding?",["Inspect the top-ranked item, affected routes, and suggested fix. Emfirge provides evidence; your team reviews and applies the final fix. Self-hosting is available in the [self-hosting](/docs/self-host) guide."])]),
];
