rebuilt("how-it-works").sections.push(
  section("graph-detail", "The graph", ["A scan reads the cloud through a read-only role and builds a connected infrastructure graph. The graph is the saved base for subsequent analysis; it is not a live write target and becomes stale as the account changes."]),
  section("workflow-detail", "Complete workflow", ["The flow is: read-only scan → fork graph → apply modeled branch change → diff the branch → re-run analysis lenses → advisory verdict.", "Use `emfirge_create_branch` to fork a completed analysis, add an `emfirge_apply_change` operation to the isolated model, then inspect `emfirge_branch_diff` and `emfirge_branch_verdict`. The verdict combines modeled native findings with available scanner lenses and reports coverage explicitly."], {code:'emfirge_create_branch({ base_analysis_id: "<analysis_id>", name: "restrict-public-access" })\nemfirge_apply_change({ branch_id: "<branch_id>", op: "modify", resource_type: "rds_instance", resource_id: "<database_id>", fields: { publicly_accessible: false } })\nemfirge_branch_diff({ branch_id: "<branch_id>" })\nemfirge_branch_verdict({ branch_id: "<branch_id>" })', language:"MCP tool calls"}),
  section("six-lenses", "The six branch-verdict lenses", ["A branch verdict compares the modeled base and proposed branch across six lenses. Each lens answers a concrete AWS question, exposes its exact verdict fields, and states what the model cannot establish."], {table:{headers:["AWS question","CombinedVerdict mapping","Honest bound","Worked example"],rows:[
    ["Security — Which native findings are new or removed?","CombinedVerdict.native_added / CombinedVerdict.native_removed","58 native rule IDs across 17 native service families cover defined families, not every possible issue.","Opening SSH to 0.0.0.0/0 adds an internet-reachable EC2 finding."],
    ["Reachability — What becomes or stops being reachable from the internet?","CombinedVerdict.newly_internet_reachable / CombinedVerdict.no_longer_internet_reachable","Modeled graph reachability, not a live connectivity probe.","Attaching a public subnet path makes a modeled service newly internet-reachable."],
    ["Blast radius — What paths are reachable from a compromised node?","No standalone blast-radius or attack-path CombinedVerdict field; related finding and attack-path payloads expose it, while the verdict summarizes resulting finding deltas.","Only modeled graph edges, known resources, and known paths.","A compromised modeled role reaching a data store appears in its attack-path payload."],
    ["IAM privilege escalation — Does the change introduce an IAM escalation path?","CombinedVerdict.introduces_privilege_escalation. Policy/action metadata from Policy Sentry informs upstream analysis; its annotations are not CombinedVerdict fields.","IAM policy/action coverage and modeled principals, not proof of exploitability.","Adding a modeled pass-role path marks privilege escalation as introduced."],
    ["Cost — What is the provisioned monthly cost delta?","CombinedVerdict.cost_delta_monthly_usd / CombinedVerdict.cost_unknown_notes","Usage-based costs remain unknown and labeled; Emfirge never fabricates them.","Adding a provisioned resource produces a monthly delta while usage-based charges remain unknown."],
    ["Limits / capacity — Which limits does the change approach or breach?","CombinedVerdict.limits_introduced / CombinedVerdict.limits_resolved","Deterministic checks, not forecasting or a live quota guarantee.","Adding resources beyond a modeled service limit adds a capacity finding."]
  ]}}),
  section("borrowed-scanners", "Borrowed scanners and coverage", ["Checkov, Trivy, and cloudsplaining run at arm's length against the branch when available; they do not become native rules. Their findings fold into `scanner_added` and `scanner_removed` alongside the same combined verdict.", "Missing executable or package, timeout, invalid or empty output, disabled scanner, or another unavailable state degrades honestly: `scanner_status` reports each state and `coverage_warnings` says the result is NOT full coverage. Do not assume all scanners always run." ]),
  section("combined-detail", "Combined verdict", ["`block`, `warn`, or `pass` combines native and scanner deltas, reachability, cost, privilege escalation, limits, and the human-readable `summary` into one advisory result. It proves the change against a model, not the live cloud: it computes a security delta and never guarantees safety.", "`coverage_warnings` is non-empty when lenses are missing or disabled. A degraded result must not be described as complete coverage or a guarantee of safety. A pass means no modeled concern was found by available analysis, not that deployment is risk-free."])
);
rebuilt("graph").sections.push(
  section("typed-graph", "Typed nodes and edges", ["Every resource a scan finds becomes a node. Every real relationship becomes a directed edge. The public internet is a first-class node, so internet reachability is a literal path. The engine models roughly 20 service types."], {bullets:["internet", "vpc", "subnet", "security_group", "ec2_instance", "load_balancer", "iam_role", "rds_instance", "s3_bucket", "lambda_function", "ecs_tasks", "api_gateway", "elasticache", "dynamodb_table", "cloudfront", "secrets_manager", "kms_key", "sqs_queue", "ebs_volume", "elastic_ip"]}),
  section("edge-types", "Relationships and effort weights", ["Edges encode `REACHES` (internet to security group), `uses_iam_role` (instance assuming a role), `can_access` (role reaching a data store), `REFERENCES_SECRET`, subnet/VPC containment, and more. Findings hang off the nodes and edges that produced them.", "Every edge type carries exploit difficulty from 0 to 3. A five-hop route of trivial steps can outrank a two-hop route needing a shell and stolen credentials: ranking is by effort, not distance."], {table:{headers:["Weight","Meaning","Example edges"],rows:[["0","Structural, not an exploit step","instance ↔ security group, subnet / VPC containment, Lambda → VPC"],["1","Trivial, automated scanners","Internet → security group, Internet → instance, CloudFront → S3 origin"],["2","Needs a step (bypass or valid call)","load balancer → instance, role → data store, Lambda → secret"],["3","Needs a shell plus credential theft","instance → IAM role, ECS task → IAM role"]]}}),
  section("derived-queries", "Derived queries", ["Attack paths are weighted shortest-path searches outward from the internet, returning routes to data ranked by effort; this is what `emfirge_attack_paths` returns.", "Blast radius is a directional outbound-only search: if one resource is compromised, everything it could reach next. Inbound edges are ignored, so the result is downstream risk, not what protects the resource.", "Chokepoints use betweenness centrality to find nodes on paths between others. Toxic combinations are 9 curated multi-signal patterns. Orphaned resources are disconnected nodes such as unattached EBS volumes or idle elastic IPs, usually cleanup/cost signals."]),
  section("coverage-counts", "Service coverage, rules, and scoring", ["The engine runs 58 deterministic rules across 17 service families: EC2 and security groups, S3, RDS, IAM, Lambda, KMS, VPC, CloudTrail, Config, CloudWatch, GuardDuty, Secrets Manager, SNS, WAF, ECS, cost, and orphaned resources.", "Findings roll into a 0–100 scan posture score (higher is safer) across security, availability, cost, and disaster recovery. Severity is context-aware: SSH open behind an ALB is not scored like SSH open to the internet. No LLM runs in scoring. This posture score is distinct from the branch verdict, which evaluates six change lenses."]),
  section("graph-limits", "Graph limits", ["The graph is a scan snapshot, not live AWS; re-scan after infrastructure changes. Coverage is roughly 20 service types, so anything outside it cannot appear in paths, blast radius, or chokepoints. Weights 0–3 are hand-assigned heuristics, not real-world exploitability measurements. Paths and blast radius are capped at 5 hops; blast radius is a downstream reachability count, not proof every step can be chained. The 9 toxic patterns are not exhaustive, and normalized scores are only approximately comparable across very different accounts."])
);
rebuilt("security").sections.push(
  section("role-detail", "Exact role permissions and trust", ["Setup creates a role with AWS's managed `SecurityAudit` policy plus a small set of extra read permissions. It has no write permissions of any kind. The role trust uses ExternalId `aws-risk-agent` to prevent confused-deputy attacks and is scoped so only Emfirge's AWS account (`000000000000`) can assume it."], {bullets:["Read-only, zero write permissions.","STS credentials are temporary, expire after one hour, and are never stored.","Delete the CloudFormation stack for instant revoke."]}),
  section("setup-detail", "Setup steps", ["Ask your assistant ‘help me set up Emfirge’ for a pre-filled deploy link. Open it in AWS, tick the IAM-resources checkbox and create the stack (about 30 seconds), copy `RoleArn` from Outputs (it starts `arn:aws:iam::`), and give the ARN back to your assistant so the scan runs."]),
  section("retention-detail", "Retention and errors", ["Scanning, rules, graph analysis, and verify-fix are deterministic pure computation; prose summaries are the only model-generated part and never run inside the MCP path. The backend stores scan data for 90 days then auto-deletes; `npx @emfirge/mcp purge --role-arn <ARN>` wipes it immediately.", "403 means access denied: check trust policy and ExternalId. 404 means the `analysis_id` was not found: run `emfirge_scan` first. 429 means the five-scans-per-account-per-day limit was reached; it resets at midnight UTC."], {table:{headers:["HTTP code","Meaning"],rows:[["403","Access denied; check trust policy and ExternalId `aws-risk-agent`."],["404","`analysis_id` not found; run `emfirge_scan` first."],["429","Daily limit of 5 scans per account; resets at midnight UTC."]]}})
);
rebuilt("privacy").sections.push(
  section("mode-definitions", "The three modes", ["`strict` (default) tokenizes recognized AWS IDs, ARNs, account IDs, resource names, and IP addresses; it is the strongest default boundary for sensitive transcripts.", "`balanced` tokenizes common identifiers such as ARNs, compute/network/IAM IDs, IPs, and account IDs while retaining selected infrastructure context; it balances context and minimization.", "`off` leaves identifiers un-tokenized so they may reach the LLM as returned; use only when raw identifiers are acceptable."]),
  section("client-config", "Changing modes and client environment", ["Use `npx @emfirge/mcp privacy` to show the current mode or `npx @emfirge/mcp privacy strict` to set strict, balanced, or off. When configuring a client directly, set `EMFIRGE_PRIVACY` in the MCP client configuration."], {code:"npx @emfirge/mcp privacy          # show current mode\nnpx @emfirge/mcp privacy strict   # set strict, balanced, or off\n\"env\": { \"EMFIRGE_PRIVACY\": \"strict\" }", language:"Terminal / client config"}),
  section("boundary-detail", "Backend and report URLs", ["The backend receives the data required for the requested scan and analysis. Credentials embedded in presigned report URLs are scrubbed before URLs are returned or displayed. Do not share raw credentials or unreviewed transcripts. Derived graph labels or descriptive values may not be recognized identifiers, so tokenization is not a completeness guarantee; review outputs against organizational policy, especially in strict mode."])
);
rebuilt("cli").sections.push(
  section("complete-commands", "Complete command reference", ["With no subcommand, the package runs as an MCP stdio server for the AI client; with a subcommand it manages installation. `install` detects Claude Desktop, Cursor, Kiro, Cline, Continue, and Codex CLI and adds the server to each config it finds. It prompts for privacy unless `--privacy` is passed; accepted values are `strict | balanced | off`, defaulting to `strict` and supporting scripts/CI. `uninstall` removes the server from all clients."], {code:"npx @emfirge/mcp install                       # wire into all detected clients\nnpx @emfirge/mcp install --privacy=balanced    # non-interactive: skip prompt\nnpx @emfirge/mcp uninstall                      # remove from all clients\nnpx @emfirge/mcp status                         # wired clients, backend URL, privacy mode\nnpx @emfirge/mcp privacy                       # show current privacy mode\nnpx @emfirge/mcp privacy strict|balanced|off   # set privacy mode everywhere\nnpx @emfirge/mcp tokens                         # list local token mappings\nnpx @emfirge/mcp purge --role-arn <ARN>         # delete local + server scan data\nnpx @emfirge/mcp --version                      # print version\nnpx @emfirge/mcp --help                         # print usage", language:"Terminal"}),
  section("behavior", "Status, privacy, tokens, and purge", ["`status` prints wired clients, backend URL, and active privacy mode. `privacy` with no argument prints the current mode; with strict, balanced, or off it updates every wired client. `tokens` lists local token → real-ID mappings at `~/.emfirge/tokens.json`; this file never leaves your machine. `purge --role-arn <ARN>` deletes the local token map and server-side records for that role permanently, with no undo."], {code:"npx @emfirge/mcp purge --role-arn <ARN>", language:"Terminal", note:"Irreversible"})
);
rebuilt("self-host").sections.push(
  section("dashboard-detail", "Dashboard URL derivation", ["The hosted default is `https://emfirge.cloud/api`. Set `EMFIRGE_BASE_URL` in each client’s MCP server config; the thin MCP calls backend endpoints and tokenizes responses locally, so a self-hosted backend behaves identically. The web dashboard URL derives from the API base by stripping `/api`, so verify-fix ‘open a PR’ links point at your own domain automatically."], {code:`{\n  "mcpServers": {\n    "emfirge": {\n      "command": "npx",\n      "args": ["-y", "@emfirge/mcp"],\n      "env": {\n        "EMFIRGE_BASE_URL": "https://emfirge.internal.acme.com/api",\n        "EMFIRGE_PRIVACY": "strict"\n      }\n    }\n  }\n}`, language:"mcp.json"}),
  section("all-env", "Complete environment configuration", ["Configure these variables in each MCP client server environment."], {table:{headers:["Variable","Type","Purpose and default"],rows:[["EMFIRGE_BASE_URL","url","Backend URL; default https://emfirge.cloud/api. Override to self-host."],["EMFIRGE_PRIVACY","strict | balanced | off","Tokenization mode; default strict."],["EMFIRGE_TRUSTED_ACCOUNT_ID","string","AWS account ID the generated role trusts; default 000000000000. Set your own account when self-hosting so setup_help trusts your scanner."],["EMFIRGE_EXTERNAL_ID","string","ExternalId required in trust policy; default aws-risk-agent."],["EMFIRGE_TEMPLATE_URL","url","CloudFormation URL used by setup_help; override to ship your own role template."]]}}),
  section("license-detail", "Open-source license", ["The MCP and a public mirror of the backend are open source under BUSL 1.1: free for non-production and small production use, converting to Apache 2.0 in 2030."])
);
rebuilt("faq").sections.push(
  section("all-questions", "FAQ: all operational questions", ["Do I need to be a security expert? No. Ask normal questions such as ‘What should I fix first?’, ‘How could someone reach my database?’, or ‘Would this change help?’; Emfirge analyzes and your assistant explains in everyday language.", "What do I need? An AWS account, target region, and read-only connection; the setup can be removed whenever you want. MCP is simply the assistant connection, and the installer wires supported desktop assistants. A browser dashboard is also available.", "Can I try it without connecting my account? Yes: the demo uses made-up infrastructure with the real analysis engine and shares nothing from your AWS account.", "Will it change or delete anything? No. It has read-only access and tests fixes on a temporary copy of the cloud map; you decide what happens next.", "Is it safe to connect? The role belongs to you, access is temporary, it cannot make AWS changes, and deleting the setup stack revokes it.", "Who can see AWS names and IDs? The backend needs real details for analysis; default privacy replaces recognized names and IDs before results reach the assistant, though some derived labels may remain. Review sensitive results before sharing.", "How long and how often? Scans usually take 30–60 seconds, larger accounts longer; the daily limit is five per AWS account. Findings, attack routes, possible fixes, and compliance checks after a scan use no additional scan.", "What after a finding? Inspect the top-ranked item and affected routes, test the suggested fix, then have your team review and apply it.", "Does it cover everything? Not yet: coverage is common AWS services and modeled relationships, not every possible issue.", "Can I self-host? Yes; follow the Self-hosting guide, with an engineer’s help if needed."], {note:"Open the Quickstart and try the demo before connecting your own account."})
);
